(function (root) {
  'use strict';
  const sign = (label, x, y, detail) => ({label, x, y, detail});
  const example = (asset, caption, limit, signs, notShown = [], reference = '#ref-glosario') => ({asset, caption, limit, signs, notShown, reference});
  root.ImagingClinicalExamples = {
    'rx-normal': example('rx-normal', 'RX frontal de referencia normal: reconocé las estructuras antes de buscar opacidades.', 'Una proyección normal no excluye enfermedad incipiente ni sustituye la lectura del estudio completo.', [sign('Campo pulmonar derecho', 28, 42, 'El aire se ve oscuro; las líneas vasculares son más claras. Derecha del paciente = izquierda de esta imagen.'), sign('Campo pulmonar izquierdo', 64, 42, 'Compará la aireación de ambos campos, sin exigir una simetría perfecta.'), sign('Silueta cardíaca', 51, 65, 'El corazón se proyecta entre los pulmones. Su tamaño se valora considerando técnica e inspiración.'), sign('Hemidiafragma derecho', 30, 61, 'Seguí su borde y el ángulo costofrénico lateral.')]),
    'rx-consolidacion': example('rx-consolidacion', 'RX AP publicada por CDC: aumento de opacidad en el lóbulo superior derecho.', 'La opacidad es sutil en esta reproducción. La imagen sola no determina el microorganismo.', [sign('Opacidad superior derecha', 29, 21, 'Compará esta zona más blanca con el campo contralateral: disminuye la transparencia aérea.'), sign('Pulmón por debajo de la opacidad', 30, 49, 'Sirve como comparación dentro de la misma placa: no toda la opacidad pulmonar ocupa un hemitórax completo.')], ['No se distingue con suficiente nitidez un broncograma aéreo para marcarlo.']),
    'rx-atelectasia': example('atlas-atelectasia', 'Atelectasia pulmonar derecha: opacidad acompañada por signos de pérdida de volumen. Es un paciente distinto del esquema.', 'Las marcas orientan regiones; no delimitan un lóbulo ni prueban la causa. La rotación puede modificar la aparente posición mediastínica.', [sign('Opacidad del hemitórax derecho', 25, 64, 'La pérdida de aire aumenta la densidad. Opacidad por sí sola no equivale a atelectasia: hay que buscar pérdida de volumen.'), sign('Menor volumen del lado afectado', 24, 35, 'Compará el espacio ocupado por el pulmón derecho con el contralateral. La combinación de opacidad y retracción apoya atelectasia.'), sign('Tráquea hacia el lado afectado', 41, 24, 'Seguí la columna aérea traqueal: se proyecta hacia la derecha del paciente (izquierda de la placa). Es compatible con tracción, pero la imagen rotada no permite atribuir todo el desplazamiento a atelectasia.'), sign('Comparación contralateral', 76, 47, 'El pulmón opuesto conserva mayor transparencia. No cuantificar hiperinsuflación compensadora con esta captura.')], ['Desplazamiento de cisuras e hilio: signos clásicos que no pueden delimitarse con seguridad aquí.', 'Elevación del hemidiafragma: su borde derecho está borrado; no señalar una altura inventada.', 'Estrechamiento intercostal e hiperinsuflación compensadora: buscar en el estudio completo, considerando técnica y rotación.', 'La placa no demuestra por sí sola tapón mucoso, tumor ni otra causa de obstrucción.']),
    'rx-derrame': example('rx-derrame', 'Derrame pleural en una proyección en decúbito: las flechas originales comparan el líquido con el pulmón.', 'Esta no es la proyección de pie del esquema; no esperar el mismo menisco.', [sign('Líquido en la zona dependiente', 38, 87, 'La opacidad se distribuye a lo largo de la región inferior de la imagen por efecto de la posición.'), sign('Pulmón más aireado', 43, 21, 'Compará la transparencia del pulmón con la banda más densa dependiente.')], ['Un menisco de la radiografía erecta no se demuestra con esta misma geometría.']),
    'rx-neumotorax': example('rx-neumotorax', 'Figura publicada con episodios y controles de neumotórax derecho. Las marcas se refieren al primer panel, arriba a la izquierda.', 'No mezclar los paneles iniciales con los controles posteriores al drenaje. La tensión es una valoración clínica urgente, no una etiqueta deducible de esta captura.', [sign('Región pleural periférica', 12, 15, 'Buscá la zona periférica sin trama vascular en el panel inicial.'), sign('Borde pulmonar señalado en el original', 18, 9, 'La flecha del artículo ayuda a seguir la línea pleural visceral separada de la pared.')], ['No inferir neumotórax a tensión ni su repercusión hemodinámica.']),
    'rx-edema': example('atlas-edema', 'Ejemplo publicado de edema pulmonar: opacidades bilaterales.', 'El patrón no determina por sí solo origen cardiogénico. La proyección y la inspiración alteran el tamaño cardíaco aparente.', [sign('Opacidades derechas', 29, 66, 'Aumento de densidad de distribución central y basal: comparar con zonas más aireadas.'), sign('Opacidades izquierdas', 73, 66, 'La afectación bilateral es una pista de distribución, no una etiología única.')], ['No se marcan líneas de Kerley ni cardiomegalia cuantificada si no son resolubles en esta reproducción.']),
    'rx-hiperinsuflacion': example('real-rx-hiper', 'Radiografía de enfisema bulloso: ejemplo de hiperclaridad y cambios de volumen.', 'El enfisema bulloso no representa todos los casos de hiperinsuflación. La RX no establece por sí sola obstrucción espirométrica.', [sign('Hiperclaridad superior derecha', 29, 23, 'Zona muy oscura con escasa trama visible, en relación con cambios bullosos del caso publicado.'), sign('Hiperclaridad basal izquierda', 79, 77, 'Compará con las regiones que conservan vasos visibles.'), sign('Contorno diafragmático bajo', 74, 88, 'Observá el perfil aplanado; integrarlo con inspiración y, cuando corresponda, proyección lateral.')]),
    'rx-nodulo': example('real-rx-nodulo', 'Opacidad focal pulmonar izquierda, ya recuadrada en la imagen de origen.', 'No medir tamaño ni diagnosticar malignidad desde esta reproducción. Un nódulo requiere comparación y caracterización adecuada.', [sign('Opacidad focal', 85, 32, 'El recuadro original sitúa una densidad redondeada en el campo superior izquierdo.'), sign('Superposición ósea', 75, 29, 'Las costillas se superponen al pulmón en RX: comprobar que una opacidad no sea solamente una suma de estructuras.')]),
    'ct-normal': example('ct-normal-55', 'Corte axial de TC de referencia normal, en ventana pulmonar.', 'Es una captura, no una serie DICOM. Un corte no permite excluir alteraciones en otros niveles.', [sign('Pulmón derecho', 29, 44, 'El parénquima aireado se ve oscuro y los vasos forman trazos o puntos más claros.'), sign('Pulmón izquierdo', 66, 44, 'Compará ambos lados en el mismo nivel y ventana.')]),
    'ct-consolidacion': example('real-ct-consolidacion', 'Caso publicado con focos de consolidación y engrosamiento septal en una fase subaguda de neumonía por Pneumocystis.', 'Coexisten varios patrones. La etiología proviene de la publicación, no de una inferencia a partir de este corte.', [sign('Foco de mayor densidad', 21, 23, 'Región anterior más opaca que el pulmón circundante; el aumento de densidad reduce la visualización del parénquima aireado.'), sign('Componente lineal asociado', 77, 55, 'También hay líneas y engrosamientos: el caso real no es una consolidación aislada idéntica al esquema.')]),
    'ct-atelectasia': example('real-ct-atelectasia', 'TC axial: atelectasias de ambos lóbulos inferiores en ventana pulmonar.', 'No inferir mecanismo obstructivo ni extensión total a partir de un solo corte.', [sign('Pulmón colapsado derecho', 34, 70, 'Opacidad posteromedial compacta: el tejido menos aireado ocupa una región retraída.'), sign('Pulmón colapsado izquierdo', 66, 72, 'La alteración también está presente del lado opuesto; no confundir con una única lesión unilateral.'), sign('Parénquima aún aireado', 23, 42, 'El contraste entre pulmón oscuro y tejido colapsado más claro facilita ubicar el cambio.')], ['El arrastre traqueal de una atelectasia extensa no debe trasladarse automáticamente a este caso bilateral.']),
    'ct-enfisema': example('atlas-enfisema', 'TC con espacios enfisematosos y bullosos.', 'La extensión y el subtipo requieren recorrer la serie; esta imagen no sustituye una prueba funcional.', [sign('Espacio de baja atenuación', 30, 33, 'Área muy oscura con reducción de estructuras vasculares visibles.'), sign('Otros espacios bullosos', 35, 17, 'Compará sus límites finos con el parénquima circundante.'), sign('Trama vascular de comparación', 26, 67, 'Los vasos más claros ayudan a reconocer dónde todavía se conserva parénquima.')]),
    'ct-bronquiectasias': example('atlas-bronquiectasias', 'Reconstrucción coronal con bronquiectasias; la orientación difiere del esquema axial.', 'No clasificar severidad ni actividad infecciosa con una sola reconstrucción.', [sign('Bronquios dilatados', 85, 72, 'Estructuras aéreas quísticas o tubulares agrupadas en la región basal izquierda.'), sign('Paredes bronquiales visibles', 88, 78, 'Seguí los contornos de estas vías aéreas anormalmente prominentes.')], ['No se marca un anillo de sello sin identificar inequívocamente la arteria acompañante.']),
    'ct-fibrosis': example('atlas-fibrosis', 'TC con cambios fibróticos subpleurales.', 'Fibrosis es un patrón; no equivale automáticamente a fibrosis pulmonar idiopática.', [sign('Espacios quísticos subpleurales', 88, 59, 'Pequeños espacios agrupados junto a la pleura, en la región de panalización del ejemplo.'), sign('Reticulación periférica', 20, 79, 'Red de líneas y distorsión del parénquima periférico. Comparar con el patrón normal.')], ['La clasificación de patrón UIP necesita distribución completa y exclusión de hallazgos alternativos.']),
    'ct-vidrio': example('real-ct-vidrio-hp', 'TC de alta resolución con áreas de vidrio esmerilado y distinta atenuación. El autor describe un caso de neumonitis por hipersensibilidad.', 'La etiología procede de la ficha del autor; no se diagnostica con este corte. Las zonas oscuras no demuestran atrapamiento aéreo sin evaluar una adquisición espiratoria.', [sign('Área de vidrio esmerilado', 15, 77, 'Aumento tenue de atenuación respecto de las regiones más oscuras, sin formar una opacidad homogénea que oculte todas las estructuras.'), sign('Vasos todavía visibles', 65, 56, 'Se conservan estructuras vasculares más blancas sobre el fondo pulmonar de atenuación aumentada.'), sign('Región de menor atenuación', 24, 61, 'Comparación dentro del mismo corte. No llamarla automáticamente normal ni atribuir su causa solo por ser más oscura.')], ['Revisar la serie completa y su técnica; la distribución en mosaico tiene más de una causa.']),
    'ct-nodulo': example('real-ct-nodulo', 'TC con nódulo pulmonar izquierdo; la flecha amarilla pertenece al archivo original.', 'No medir ni asignar riesgo oncológico desde una imagen reducida. Se necesitan tamaño, morfología, antecedentes y evolución.', [sign('Nódulo', 77, 41, 'Opacidad focal redondeada dentro del pulmón, indicada por la flecha de origen.'), sign('Pulmón alrededor del nódulo', 72, 34, 'Comparar la lesión con el parénquima aireado y los vasos vecinos.')]),
    'ct-embolia': example('atlas-tep', 'Angio-TC con defectos de repleción señalados en la imagen original.', 'Se interpreta con contraste y ventana apropiada. La captura no establece por sí sola gravedad ni tratamiento.', [sign('Defecto de repleción derecho', 36, 50, 'Zona de menor atenuación dentro de una arteria contrastada; seguir la flecha del original.'), sign('Defecto contralateral', 58, 49, 'Compará el material menos opacificado con el contraste brillante que lo rodea.'), sign('Contraste intravascular', 51, 32, 'El contraste permite distinguir la luz opacificada del defecto; no es la ventana pulmonar del esquema.')], [], '#ref-tep'),
    'us-normal': example('eco-video-1', 'Fotograma y video de deslizamiento pleural: referencia de un signo normal en la zona explorada.', 'Una imagen fija no demuestra deslizamiento; reproducí el video. El signo local normal no implica que todo el paciente esté sano.', [sign('Línea pleural', 51, 51, 'Ubicá la interfaz brillante y luego observá su movimiento respiratorio en el clip.'), sign('Pared torácica superficial', 51, 26, 'Los tejidos superficiales quedan por encima de la línea pleural.')], ['Las líneas A deben buscarse como repeticiones horizontales; no se señalan si no son nítidas en este fotograma.'], '#ref-lus'),
    'us-lineas-b': example('eco-video-3', 'Fotograma y video con artefactos verticales tipo B.', 'Las líneas B no son específicas de edema cardiogénico. Evaluar distribución, pleura y contexto.', [sign('Línea pleural de origen', 55, 46, 'Punto de referencia desde donde nacen los artefactos, no desde la piel.'), sign('Artefacto vertical', 63, 69, 'Seguí la banda brillante hacia el fondo; en el clip evaluá su continuidad y movimiento con la pleura.')], [], '#ref-lus'),
    'us-consolidacion': example('eco-video-5', 'Fotograma y video de consolidación subpleural con aspecto tisular.', 'La ecografía solo ve lesiones que alcanzan la pleura o tienen una ventana acústica adecuada. No toda consolidación es neumonía.', [sign('Aspecto tisular', 53, 56, 'El pulmón pierde el aspecto de artefactos repetidos y adquiere una textura parecida a un órgano sólido.'), sign('Ecos brillantes intralesionales', 53, 36, 'Buscá ecos aéreos dentro del tejido. Para llamarlos broncograma dinámico hay que comprobar movimiento en video.')], [], '#ref-lus'),
    'us-atelectasia': example('real-us-atelectasia', 'Figura 1a (panel izquierdo): atelectasia compresiva con derrame. El panel derecho 1b corresponde a una masa, no a la misma atelectasia.', 'El color Doppler es parte del original. No permite inferir por sí solo viabilidad, etiología ni mecanismo obstructivo.', [sign('Pulmón atelectásico', 26, 67, 'Tejido colapsado del panel izquierdo, rodeado por líquido.'), sign('Líquido pleural', 19, 40, 'Espacio oscuro que proporciona una ventana para ver el pulmón comprimido.'), sign('Señal Doppler intrapulmonar', 29, 49, 'Color dentro del tejido en el panel a; no confundirlo con aire o con líquido libre.')], ['Para distinguir un broncograma estático de uno dinámico y evaluar el pulso pulmonar se necesita una secuencia; no se demuestran aquí.'], 'https://link.springer.com/article/10.1186/s13089-024-00359-4'),
    'us-derrame': example('eco-video-7', 'Fotograma y video de líquido pleural y tejidos adyacentes.', 'La apariencia anecoica no determina la composición del líquido ni indica por sí sola una punción.', [sign('Espacio líquido', 65, 46, 'Región oscura sin el patrón de pulmón aireado.'), sign('Tejido adyacente al líquido', 47, 58, 'Reconocé la interfaz con el líquido y revisá el clip completo. Esta captura aislada no basta para identificar con seguridad todas las estructuras ni su movilidad.')], [], '#ref-lus'),
    'us-complejo': example('real-us-complejo', 'Figura suplementaria S3a, panel izquierdo: tabiques y bolsillos de líquido tras pleurodesis con talco. Los paneles derechos muestran mediciones del diafragma.', 'Es un ejemplo de complejidad pleural posprocedimiento: no presentarlo como empiema ni atribuir infección solo por los tabiques.', [sign('Tabiques pleurales', 23, 49, 'Líneas ecogénicas que dividen el líquido en el panel izquierdo.'), sign('Bolsillo de líquido', 22, 41, 'Espacio más oscuro entre las estructuras que compartimentan la cavidad.'), sign('Otra región septada', 29, 57, 'Seguí los puentes ecogénicos dentro del compartimento pleural; no corresponden a líneas B.')], ['La composición, esterilidad y necesidad de drenaje no se determinan desde esta captura.'], 'https://link.springer.com/article/10.1186/s13089-024-00359-4'),
    'us-neumotorax': example('eco-video-4', 'Video publicado de punto pulmonar; el fotograma sirve para ubicar la región pleural a observar.', 'El punto pulmonar es dinámico. Ausencia de deslizamiento aislada no confirma neumotórax y ausencia de punto pulmonar no lo excluye.', [sign('Región pleural', 65, 43, 'Reproducí el clip y seguí la pleura durante la respiración.'), sign('Zona para buscar la transición', 55, 48, 'Observar en movimiento la alternancia entre contacto pulmonar y región sin deslizamiento. No diagnosticar la transición a partir de esta marca fija.')], ['No se superponen marcas al video en movimiento: estas referencias solo corresponden al fotograma.'], '#ref-lus')
  };
})(typeof window === 'undefined' ? globalThis : window);
